import os
import stripe
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("orders")
stripe.api_key = os.environ["STRIPE_API_KEY"]


@mcp.tool()
def refund_order_payment(payment_intent_id: str, amount_cents: int = None, reason: str = "requested_by_customer") -> dict:
    args = {"payment_intent": payment_intent_id, "reason": reason}
    if amount_cents is not None:
        if amount_cents <= 0:
            return {"ok": False, "error": "amount_cents must be positive"}
        args["amount"] = amount_cents
    try:
        r = stripe.Refund.create(**args)
    except stripe.error.StripeError as e:
        return {"ok": False, "error": str(e)}
    return {
        "ok": True,
        "refund_id": r.id,
        "status": r.status,
        "amount": r.amount,
        "currency": r.currency,
        "payment_intent": payment_intent_id,
    }

import sqlite3
from dataclasses import dataclass
from typing import Optional
from langchain_core.tools import tool

DB = "store.db"


@dataclass
class CreditResult:
    success: bool
    message: str
    new_balance: Optional[float] = None
    credit_id: Optional[int] = None


@tool
def issue_store_credit_for_return(order_id: int, customer_id: int, amount: float, note: str = "") -> CreditResult:
    if amount <= 0:
        return CreditResult(False, "Amount must be positive")
    cn = sqlite3.connect(DB)
    try:
        cur = cn.cursor()
        order = cur.execute(
            "SELECT total FROM orders WHERE id = ? AND customer_id = ?",
            (order_id, customer_id),
        ).fetchone()
        if order is None:
            return CreditResult(False, "Order not found for this customer")
        done = cur.execute(
            "SELECT COALESCE(SUM(amount), 0) FROM store_credits WHERE order_id = ?",
            (order_id,),
        ).fetchone()[0]
        if done + amount > order[0]:
            return CreditResult(False, f"Credit would exceed order total of {order[0]:.2f}")
        cur.execute(
            "INSERT INTO store_credits (order_id, customer_id, amount, note) VALUES (?, ?, ?, ?)",
            (order_id, customer_id, amount, note),
        )
        cid = cur.lastrowid
        cur.execute(
            "UPDATE customers SET credit_balance = credit_balance + ? WHERE id = ?",
            (amount, customer_id),
        )
        bal = cur.execute(
            "SELECT credit_balance FROM customers WHERE id = ?", (customer_id,)
        ).fetchone()
        if bal is None:
            cn.rollback()
            return CreditResult(False, "Customer not found")
        cn.commit()
        return CreditResult(True, "Store credit issued", bal[0], cid)
    except sqlite3.Error as e:
        cn.rollback()
        return CreditResult(False, f"Database error: {e}")
    finally:
        cn.close()
